technical.EquipTrait:
new AdventurerTrait
			{
				IconName = "Icons3_55",
				DisplayName = "@triune_shield",
				Description = "@triune_shield_desc",
				ApplyGroupBuffs = (ActiveTrait trait, CombatantItemData target, object context) =>
				{
					if (target == trait.Self)
					{
						target.ApplyBuff(AdventurerTrait.FireResist, trait.Quality);
						target.ApplyBuff(AdventurerTrait.ShadowResist, trait.Quality);
						target.ApplyBuff(AdventurerTrait.PoisonResist, trait.Quality);
					}
				}
			}

new AdventurerTrait
			{
				DisplayName = "@scroll_of_healing",
				IconName = "Icons3_60",
				GetDescription = (ActiveTrait trait) => Translation.TranslateOnly("@healing_potion_effect", (float)scrollHealingAmt * trait.Quality),
				WarTick = (ActiveTrait trait, WarProgress war) =>
				{
					_healingScroll(trait, scrollHealingAmt, war);
				},
				QuestTick = (ActiveTrait trait, QuestProgress q) =>
				{
					_healingScroll(trait, scrollHealingAmt, q);
				},
				ArenaTick = (ActiveTrait trait, Arena a) =>
				{
					_healingScroll(trait, scrollHealingAmt, a);
				},
				DungeonHealingTick = (ActiveTrait trait, DungeonProgress d) =>
				{
					_healingScroll(trait, scrollHealingAmt, d);
				}
			}

new AdventurerTrait
			{
				DisplayName = "@scroll_of_aoe_healing",
				IconName = "Icons3_61",
				GetDescription = (ActiveTrait trait) => Translation.TranslateOnly("@scroll_of_aoe_healing_effect", (float)aoeHealingAmt * trait.Quality),
				WarTick = (ActiveTrait trait, WarProgress war) =>
				{
					_aoeHealScroll(trait, war.Soldiers, 4 / war.Soldiers.Count, aoeHealingAmt, war);
				},
				QuestTick = (ActiveTrait trait, QuestProgress q) =>
				{
					_aoeHealScroll(trait, q.Parent.Contents, 1f, aoeHealingAmt, q);
				},
				DungeonHealingTick = (ActiveTrait trait, DungeonProgress d) =>
				{
					_aoeHealScroll(trait, d.Party, 1f, aoeHealingAmt, d);
				}
			}

new AdventurerTrait
			{
				DisplayName = "@scroll_of_damage",
				Description = "@scroll_of_damage_effect",
				IconName = "Icons3_63",
				DungeonCombatTick = (ActiveTrait trait, DungeonProgress dungeon) =>
				{
					if (dungeon.Stage.IsBoss && dungeon.StageTick == 5)
					{
						dungeon.StageProgress += trait.Self.GetCombatPower() * 4;
					}
				}
			}

new AdventurerTrait
			{
				DisplayName = "@scroll_of_energy",
				GetDescription = (ActiveTrait trait) => Translation.TranslateOnly("@scroll_of_energy_trait", (float)scrollEnergyAmt * trait.Quality),
				IconName = "Icons3_62",
				QuestTick = (ActiveTrait trait, QuestProgress quest) =>
				{
					_restoreEnergy(trait, quest.Parent.Contents, scrollEnergyAmt);
				},
				DungeonHealingTick = (ActiveTrait trait, DungeonProgress dungeon) =>
				{
					_restoreEnergy(trait, dungeon.Party, scrollEnergyAmt);
				}
			}

