				GetDescription = (ActiveTrait trait) => Translation.TranslateOnly("@lifebloom_amulet_trait_desc", 2f * trait.Quality / 2f),
				IconName = "Icons2_213",
				ArenaTick = (ActiveTrait trait, Arena arena) =>
				{
					_lifebloomEffect(trait, new List<CombatantItemData> { trait.Self }, 1f, arena);
				},
				QuestTick = (ActiveTrait trait, QuestProgress quest) =>
				{
					_lifebloomEffect(trait, quest.Parent.Contents, 0.5f, quest);
				},
				WarTick = (ActiveTrait trait, WarProgress war) =>
				{
					_lifebloomEffect(trait, war.Soldiers, 4 / war.Soldiers.Count, war);
				},
				DungeonHealingTick = (ActiveTrait trait, DungeonProgress dungeon) =>
				{
					_lifebloomEffect(trait, dungeon.Combatants, 0.8f, dungeon);
				}
			}

