technical.OnUnlock:
(GamePlayer ply) =>
			{
				foreach (Shop element in ply.GetElements<Shop>())
				{
					element.UpdateUpgrades();
				}
			}

(GamePlayer ply) =>
			{
				foreach (Outfitter element in ply.GetElements<Outfitter>())
				{
					element.CheckAutomated();
				}
			}

(GamePlayer ply) =>
			{
				foreach (TrackSwitch element in ply.GetElements<TrackSwitch>())
				{
					element.UpdateTrackSwitch();
					if ((bool)element.World)
					{
						element.World.UpdateIO();
					}
				}
			}

(GamePlayer ply) =>
			{
				ply.ForestSettings = new ForestSettings();
				ply.ForestSettings.AddWorkerCount(ForestWorker.Unassigned, 3);
				ply.ForestSettings.AddWorkerCount(ForestWorker.Hunter, 1);
				ply.ForestSettings.AddWorkerCount(ForestWorker.Logger, 1);
				ply.ForestSettings.AddWorkerCount(ForestWorker.Forager, 1);
				ply.AddTech("forest_wood_log");
				ply.AddTech("forest_wolf_hide");
				ply.AddTech("forest_bird_egg");
				GameUI.Instance.UpdateForestCrewButton();
				TutorialUI.Instance?.ShowForestArrow(show: true);
			}

(GamePlayer ply) =>
			{
				foreach (Stockpile element in ply.GetElements<Stockpile>())
				{
					element.UpdateOutput();
				}
			}

(GamePlayer ply) =>
			{
				foreach (TrainingGrounds element in ply.GetElements<TrainingGrounds>())
				{
					element.UpdateSlotCount();
				}
			}

(GamePlayer ply) =>
			{
				foreach (TrainingGrounds element2 in ply.GetElements<TrainingGrounds>())
