				{
					if (!element2.IsOutput)
					{
						element2.SetOutput(output: false);
					}
				}
			}

(GamePlayer ply) =>
			{
				ply.AddTech("simple_burial");
				ply.AddTech("fallen_heroes");
				foreach (WarEffort element in ply.GetElements<WarEffort>())
				{
					element.UpdateIO();
					element.World.UpdateIO();
				}
			}

