technical.CalcStat:
(ActiveTrait trait, EquipStat stat, float current) =>
		{
			if (stat == EquipStat.Armor)
			{
				InventoryItem equippedItem = ((HumanItemData)trait.Self).GetEquippedItem(EquipmentSlot.OffHand);
				if (equippedItem?.Type is WeaponItemType { WeaponType: WeaponType.Shield })
				{
					current += (float)equippedItem.GetAppraiserStat(AppraiserStat.Armor) * trait.Quality;
				}
			}
			return current;
		}

