technical.ExecuteQuest:
(QuestProgress qp) =>
		{
			float num = 15f + (float)qp.Quest.Difficulty / 50f;
			foreach (HumanItemData content in qp.Parent.Contents)
			{
				float num2 = num * ((float)qp.Quest.Difficulty / (float)content.GetBaseDamage(qp));
				content.TakeDamage(Mathf.RoundToInt(SeededRandom.Global.RandomRange(num2 / 1.3f, num2 * 1.3f)), qp);
			}
		}

